// Function to perform iterative binary search on a sorted array
fun Binary_Search(@init<table> collection, target, size):
    // Initialize lower bound index
    low = 0

    // Initialize upper bound index
    high = size - 1

    // Continue searching while lower bound is less than or equal to upper bound
    while (low <= high):
        // Calculate middle index of current search range
        mid = (low + high) / 2

        // Get value at the middle index
        @mark<mid, highlight, yellow> val = collection[mid]

        // If middle value equals target, return the middle index
        if (val == target):
            @mark<mid, highlight, green> return mid
        end if

        // If middle value is less than target, search right half
        if (val < target):
            @mark<low, outline, yellow> low = mid + 1
        end if

        // If middle value is greater than target, search left half
        if (val > target):
            @mark<high, outline, yellow> high = mid - 1
        end if
    end while

    // Target not found in array
    @log<warn, "Not found"> return -1
end fun

// Example usage of the binary search function
result = Binary_Search([1, 3, 5, 7, 9, 11, 13], 7, 7)
