fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)
    start = 0
    end = n - 1
    swapped = True

    while (swapped == True):
        swapped = False

        // Left to right pass
        for (i = start, i < end, i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap (array[i], array[i + 1])
                swapped = True
            end if
        end for

        if (swapped == False):
            break
        end if

        // Move the end pointer one position back
        end -= 1

        // Right to left pass
        for (i = end, i > start, i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap (array[i], array[i - 1])
                swapped = True
            end if
        end for

        // Move the start pointer one position forward
        start += 1
    end while

    return array
end fun

