// Cocktail Shaker Sort implementation
// This algorithm alternates between left-to-right and right-to-left passes
// It bubbles the largest and smallest elements to their correct positions
// in each iteration, effectively "shaking" the array back and forth

fun Cocktail_Shaker_Sort(@init<table> array):
    n = length(array)

    // Initialize boundaries for the unsorted portion of the array
    left = 0
    right = n - 1

    // Continue sorting while there are elements to sort
    while (left < right):
        // First pass: left to right
        // Bubble the largest unsorted element to the right
        swapped = False
        for (i = left, i < right, i += 1):
            @mark<i, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> swap (array[i], array[i + 1])
                swapped = True
            end if
        end for

        // After this pass, the largest element is at the rightmost position
        right -= 1

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if

        // Second pass: right to left
        // Bubble the smallest unsorted element to the left
        for (i = right, i > left, i -= 1):
            @mark<i, outline, yellow> if (array[i] < array[i - 1]):
                @mark<i, highlight, green> swap (array[i], array[i - 1])
                swapped = True
            end if
        end for

        // After this pass, the smallest element is at the leftmost position
        left += 1

        // If no swaps occurred, the array is sorted
        if (swapped == False):
            break
        end if
    end while

    return array
