// Function to perform Comparison Counting Sort
fun Comparison_Counting_Sort(@init<table> array): 
    // Get the length of the input array
    n = length(array)

    // Create an array to store counts for each element
    count = arr(n)

    // Initialize all elements in count array to zero
    for (i = 0, i < n, i += 1):
        count[i] = 0
    end for

    // For each pair of elements, compare them and increment count accordingly
    for (i = 0, i < n - 1, i += 1):
        for (j = i + 1, j < n, j += 1):
            // If element at index i is less than element at index j,
            // increment count for element at index j
            @mark<j, text, fg> if (array[i] < array[j]):
                count[j] += 1
            else:
                // Otherwise increment count for element at index i
                @mark<i, text, fg> count[i] += 1
            end if
        end for
    end for

    // Create a temporary array to hold the sorted result
    sorted_array = arr(n)

    // Place each element in its correct position based on count
    for (i = 0, i < n, i += 1):
        @mark<i, highlight, green> sorted_array[count[i]] = array[i]
    end for

    // Copy the sorted values back to original array
    for (i = 0, i < n, i += 1):
        array[i] = sorted_array[i]
    end for

    // Return the sorted array
    return array

end fun

