fun Dutch_National_Flag(@init<table> array):
    n = length(array)

    // Initialize three pointers
    low = 0       // points to the end of 0s section
    mid = 0       // traverses the array
    high = n - 1  // points to the start of 2s section

    // Traverse the array until mid crosses high
    while (mid <= high):
        @mark<mid, outline, yellow> if (array[mid] == 0):
            // swap element at mid with element at low
            @mark<low, highlight, green> swap(array[low], array[mid])
            low += 1
            mid += 1
        else if (array[mid] == 1):
            // 1s are already in correct place, move mid pointer
            mid += 1
        else:
            // swap element at mid with element at high
            @mark<high, highlight, green> swap(array[mid], array[high])
            high -= 1
            // do not increment mid because swapped element 
            // from high might be 0 or 2 that needs processing
        end if
    end while

    return array
end fun

