// Function to maintain the max heap property
fun Max_Heapify(@init<table> array, @init<int> heap_size, @init<int> i):
    left = 2 * i + 1
    right = 2 * i + 2
    largest = i

    // Check if left child exists and is greater than root
    if (left < heap_size AND array[left] > array[largest]):
        @mark<left, outline, yellow> largest = left
    end if

    // Check if right child exists and is greater than largest so far
    if (right < heap_size AND array[right] > array[largest]):
        @mark<right, outline, yellow> largest = right
    end if

    // If largest is not root, swap and continue heapifying
    if (largest != i):
        @mark<i, highlight, green> swap(array[i], array[largest])
        Max_Heapify(array, heap_size, largest)
    end if
end fun

// Function to build a max heap from an unsorted array
fun Build_Max_Heap(@init<table> array):
    n = length(array)
    // Start from last non-leaf node and heapify each node
    for (i = n / 2 - 1, i >= 0, i -= 1):
        @mark<i, outline, yellow> Max_Heapify(array, n, i)
    end for
end fun

// Main Heap Sort function
fun Heap_Sort(@init<table> array):
    n = length(array)

    // Build max heap
    Build_Max_Heap(array)

    // Extract elements from heap one by one
    for (i = n - 1, i > 0, i -= 1):
        @mark<i, highlight, green> swap(array[0], array[i])
        Max_Heapify(array, i, 0)
    end for

    return array
end fun

