    // Initialize two pointers: one at start and one at end
    left = 0
    right = n - 1

    // Loop while left pointer is less than right pointer
    while (left < right):
        // If elements at both pointers don't match, it's not a palindrome
        if (array[left] != array[right]):
            @mark<left, highlight, red> return 0  // Not a palindrome
        end if

        // Move left pointer forward
        left += 1
        // Move right pointer backward
        right -= 1

        @mark<left, outline, yellow> @mark<right, outline, yellow>
    end while

    // If we reach here, all elements matched, so it's a palindrome
    @mark<left, highlight, green> return 1  // Is a palindrome
end fun

// Main execution: test the function with a sample array
test_array = [1, 2, 3, 2, 1]
result = is_palindrome(test_array)
