// Function to perform Lomuto partitioning on an array
// It partitions the array around the last element (pivot)
// and returns the final index of the pivot after partitioning
fun Lomuto_Partition(@init<table> array, low, high): 
    // choose the pivot - last element of sub-array
    @mark<high, highlight, yellow> pivot = array[high]

    // index of smaller element (boundary for elements < pivot)
    i = low - 1

    for (j = low, j < high, j += 1):
        // check to see if current element is smaller than pivot
        @mark<j, outline, yellow> if (array[j] < pivot):
            i += 1
            @mark<i, highlight, green> swap (array[i], array[j]) 
        end if
    end for

    @mark<i, highlight, green> swap (array[i + 1], array[high]) 

    return i + 1  // return the final index of the pivot
end fun

// Main execution block
// Create an example array to test the partition function
@init<table> test_array = [10, 7, 8, 9, 1, 5]
// Call the Lomuto_Partition function with the test array
// Partitioning will occur from index 0 to length-1
result = Lomuto_Partition(test_array, 0, 5)
// Print the result which is the final index of the pivot
@log<info, "Pivot final index is: " + result>
