    Merge_Sort_Helper(array, temp, left, mid)

    // Recursively sort second half
    Merge_Sort_Helper(array, temp, mid + 1, right)

    // Merge the sorted halves
    Merge(array, temp, left, mid, right)
end fun

fun Merge(@init<table> array, @init<table> temp, left, mid, right):
    // Copy data to temporary array
    for i = left to right:
        temp[i] = array[i]
    end for

    // Initialize pointers for left, right and merged array
    i = left       // initial index of left subarray
    j = mid + 1    // initial index of right subarray
    k = left       // initial index of merged array

    // Merge the temp arrays back into array[left..right]
    while ((i <= mid) and (j <= right)):
        if (temp[i] <= temp[j]):
            array[k] = temp[i]
            i += 1
        else:
            array[k] = temp[j]
            j += 1
        end if
        k += 1
    end while

    // Copy remaining elements of left subarray if any
    while (i <= mid):
        array[k] = temp[i]
        i += 1
        k += 1
    end while

    // Copy remaining elements of right subarray if any
    while (j <= right):
        array[k] = temp[j]
        j += 1
        k += 1
    end while
end fun

