// Odd-Even Transposition Sort implementation
// This algorithm works by repeatedly passing through the array,
// comparing adjacent elements and swapping them if they are in wrong order.
// It alternates between odd and even passes until the array is sorted.

fun Odd_Even_Transposition_Sort(@init<table> array): 
    n = length(array)

    // If array has less than 2 elements, it's already sorted
    if (n < 2):
        return array
    end if

    // Continue sorting while the array is not fully sorted
    sorted = false
    while (!sorted):
        sorted = true

        // Odd pass: compare elements at odd indices
        for (i = 1, i < n - 1, i += 2):
            @mark<i, outline, yellow> @mark<i + 1, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> @mark<i + 1, highlight, green> swap(array[i], array[i + 1])
                sorted = false
            end if
        end for

        // Even pass: compare elements at even indices
        for (i = 0, i < n - 1, i += 2):
            @mark<i, outline, yellow> @mark<i + 1, outline, yellow> if (array[i] > array[i + 1]):
                @mark<i, highlight, green> @mark<i + 1, highlight, green> swap(array[i], array[i + 1])
                sorted = false
            end if
        end for
    end while

    return array
end fun

