// Function to perform quickselect using Lomuto partitioning
// Finds the k-th smallest element in the array (1-indexed)
fun Quickselect(@init<table> array, low, high, k):
    // Base case: if low equals high, we've found our element
    if (low == high):
        return array[low]
    end if

    // Partition the array and get the pivot index
    @mark<low, highlight, yellow> pivot_index = Lomuto_Partition(array, low, high)

    // If the pivot is at the k-th position, return it
    if (pivot_index == k - 1):
        return array[pivot_index]
    // If k is less than the pivot index, search in the left subarray
    elif (k - 1 < pivot_index):
        return Quickselect(array, low, pivot_index - 1, k)
    // Otherwise, search in the right subarray
    else:
        return Quickselect(array, pivot_index + 1, high, k)
    end if
end fun

// Main function to initiate quickselect
fun Find_Kth_Smallest(@init<table> arr, k):
    n = length(arr)

    // Check if k is valid
    if (k <= 0 or k > n):
        @log<"Invalid k value"> return -1
    end if

    // Call quickselect to find the k-th smallest element
    result = Quickselect(arr, 0, n - 1, k)

    return result
end fun

