// Function to remove duplicates from a sorted array in place
// It moves unique elements to the front and returns count of unique elements
fun remove_duplicates(@init<table> array):
    n = length(array)

    // Handle edge case of empty array
    if (n == 0):
        return 0
    end if

    // Index to track position where next unique element should go
    @mark<i, outline, yellow> writeIndex = 1

    // Iterate through array starting from second element
    for (i = 1, i < n, i += 1):
        // If current element is different from previous one,
        // it's a new unique element
        if (array[i] != array[i - 1]):
            // Place unique element at writeIndex
            @mark<i, text, fg> array[writeIndex] = array[i]
            // Move writeIndex forward
            @mark<writeIndex, highlight, green> writeIndex += 1
        end if
    end for

    // Return number of unique elements
    return writeIndex
end fun

// Example usage
original_array = [1, 1, 2, 2, 3, 4, 4, 5]
result = remove_duplicates(original_array)
