// Returns the number of unique elements
fun remove_duplicates(@init<table> array):
    n = length(array)

    // Handle edge case: empty array
    if (n == 0):
        return 0
    end if

    // Index for the next unique element
    @mark<i, outline, yellow> i = 0

    // Traverse the array starting from second element
    for (j = 1, j < n, j += 1):
        // If current element is different from previous one
        if (array[j] != array[i]):
            // Move index forward
            i += 1
            // Copy unique element to next position
            @mark<j, highlight, green> array[i] = array[j]
        end if
    end for

    // Return count of unique elements (index + 1)
    return i + 1
end fun

