// Function to perform selection sort on an array
fun Selection_Sort(@init<table> array): 
    // Get the length of the array
    n = length(array)

    // Outer loop: iterate through all index positions except the last
    for (i = 0, i < n - 1, i += 1):
        // Assume the current index position holds the minimum element
        @mark<i, outline, yellow> minIdx = i

        // Inner loop: find the actual minimum element in the remaining unsorted portion
        for (j = i + 1, j < n, j += 1):
            @mark<j, outline, yellow> if (array[j] < array[minIdx]):
                @mark<j, text, fg> minIdx = j  // Update minimum index if smaller element found
            end if
        end for

        // Swap the found minimum element with the first element of unsorted portion
        @mark<minIdx, highlight, green> swap(array[i], array[minIdx])
    end for

    // Return the sorted array
    return array
end fun

