// Shell Sort implementation with gaps n/2, n/4, ..., 1
fun Shell_Sort(@init<table> array): 
    n = length(array)

    // Start with gap size of n/2 and keep halving it
    gap = n / 2

    // Continue until gap becomes 0
    while (gap > 0):
        // Perform insertion sort for elements at distance 'gap'
        for (i = gap, i < n, i += 1):
            @mark<i, outline, yellow> temp = array[i]

            // Shift earlier gap-sorted elements up until correct location found
            j = i
            while (j >= gap AND array[j - gap] > temp):
                @mark<j, text, fg> array[j] = array[j - gap]
                j -= gap
            end while

            // Put temp (the original array[i]) in its correct location
            @mark<j, highlight, green> array[j] = temp
        end for

        // Reduce the gap for next iteration
        gap = gap / 2
    end while

    return array
end fun

