// Function to find two indices in a sorted array that sum to the target
fun Two_Sum_Sorted(@init<table> array, target):
    // Initialize two pointers: left at start, right at end
    left = 0
    right = length(array) - 1

    // Loop while left pointer is less than right pointer
    while (left < right):
        // Calculate current sum of values at left and right indices
        current_sum = array[left] + array[right]

        // If current sum equals target, we found our pair
        if (current_sum == target):
            @log<info, "Pair found at indices"> return [left, right]
        end if

        // If current sum is less than target, move left pointer right
        if (current_sum < target):
            left += 1
        else:
            // If current sum is greater than target, move right pointer left
            right -= 1
        end if
    end while

    // No valid pair was found
    return [-1, -1]
end fun

